def name_operands(region,function_address,operation):
    if region=='Action' and function_address in FUNCTIONS:
        operation=operation.replace('CALL #C6F4','CALL @Action.MultiplySigned16.Entry')
        for address,expression in ((0xCF0B,'FirstPoint+FRenderProjectedPoint.Second'),(0xCF0D,'FirstPoint+FRenderProjectedPoint.First'),(0xCF1B,'SecondPoint+FRenderProjectedPoint.Second'),(0xCF1D,'SecondPoint+FRenderProjectedPoint.First')):
            operation=operation.replace('(#'+format(address,'04X')+')','(@ActionClipProductsState.'+expression+')')
        for _,field,address,_,_ in DETAILS.values():
            for offset,part in ((0,'LowWord'),(2,'HighWord')):
                operation=operation.replace('(#'+format(address+offset,'04X')+')','(@ActionClipProductsData.'+field+'.'+part+')')
        operation=operation.replace('LD BC, #0000','LD BC, @ActionClipProductConst.ZeroBound').replace('LD BC, #005F','LD BC, @ActionClipProductConst.FirstMaximum').replace('LD BC, #00FF','LD BC, @ActionClipProductConst.SecondMaximum')
    for point in ('FirstPoint','SecondPoint'):
        operation=operation.replace('@ActionClipProductsState.'+point+'+FRenderProjectedPoint.','@ActionClipPoints.'+point+'.')
    return operation

# Второй вариант начинает чтение BC сразу после EX DE,HL.
for address in (0xC4B5,0xC4D4):
    COMMENTS[address+10]=COMMENTS.pop(address+11)
